package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A sheet's settings in force on its today: the clerk limit (two decimals; null: no limit) the floor (two
 *  decimals) and the terms (days; a claim's due-by is its date plus them) and the late percent (two decimals) and the
 *  policy date (null: the sheet's today; a claim dated before it rounds half up, on or after it half to even) and the
 *  period numbering from (null: off; on or after it, by the sheet's today, a claim opened is numbered within its
 *  period) and the grades' own terms (days, by grade; a grade without its own uses the sheet's terms) and the cap
 *  (two decimals; null: none; a person's due-total is at most it) and the proof threshold (two decimals; null: none); and every value of the dated ones; and the permission matrix (not dated). */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, BigDecimal cap,
        BigDecimal proofThreshold, SettingHistory history, Permissions permissions) {
}
package net.officefloor.hq.app.setting;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** The settings as the screen shows them: the clerk limit with two decimals ('' when there is none) and the floor
 *  with two decimals and the terms in days and the late percent with two decimals and the policy date (yyyy-mm-dd; '' when blank) and the period numbering from (yyyy-mm-dd; '' when off) and each grade's own
 *  terms in days ('' when it has none: it uses the sheet's terms) and the cap with two decimals ('' when there is none) and the proof threshold with two decimals ('' when there is none), all as in force on the sheet's today; and every value
 *  recorded for each dated setting, by key, oldest from-date first; and the permission matrix, by action ('' when blank). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap,
        Map<String, List<Dated>> dated, String proofThreshold, Map<String, String> perms) {

    /** A dated setting's value ('' when blank) and the date (yyyy-mm-dd) it is in force from. */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Settings s) {
        return new SettingsResponse(SettingsResponse.text(s.clerkLimit()), SettingsResponse.text(s.floor()),
                String.valueOf(s.terms()), SettingsResponse.text(s.latePct()),
                s.policyDate() != null ? s.policyDate().toString() : "",
                s.periodNumberingFrom() != null ? s.periodNumberingFrom().toString() : "", gradeTerms(s),
                SettingsResponse.text(s.cap()), dated(s), SettingsResponse.text(s.proofThreshold()),
                s.permissions().entries());
    }

    private static Map<String, List<Dated>> dated(Settings s) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (String key : SettingHistory.KEYS) {
            List<Dated> values = new ArrayList<>();
            s.history().of(key).forEach((from, value) -> values.add(new Dated(from.toString(), value != null ? value : "")));
            dated.put(key, values);
        }
        return dated;
    }

    private static Map<String, String> gradeTerms(Settings s) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = s.gradeTerms().get(grade);
            terms.put(grade, days != null ? String.valueOf(days) : "");
        }
        return terms;
    }

    static String text(java.math.BigDecimal limit) {
        return limit != null ? limit.toPlainString() : "";
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's settings: the dated ones (see SettingHistory) one value per key and from-date, the policy date and
 *  the period numbering from (not dated) on the sheet's row. */
@Repository
public class SettingRepository {

    /** The floor of a sheet before any is in force. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms of a sheet before any are in force. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent of a sheet before any is in force. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings in force on its today. */
    public Settings of(String sheetId) {
        SettingHistory history = history(sheetId);
        LocalDate today = today(sheetId);
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = history.gradeTermsOn(grade, today);
            if (days != null) {
                gradeTerms.put(grade, days);
            }
        }
        return new Settings(sheetId, history.clerkLimitOn(today), history.floorOn(today), history.termsOn(today),
                history.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId), gradeTerms,
                history.capOn(today), history.proofThresholdOn(today), history, permissions(sheetId));
    }

    /** Every value of the sheet's dated settings, by key and from-date. */
    public SettingHistory history(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new HashMap<>();
        jdbc.query("SELECT setting_key, from_date, val FROM setting_value WHERE sheet_id = ?", rs -> {
            values.computeIfAbsent(rs.getString(1), k -> new TreeMap<>())
                    .put(rs.getObject(2, LocalDate.class), rs.getString(3));
        }, sheetId);
        return new SettingHistory(values);
    }

    /** Record the dated setting's value (null: blank) from the from-date, replacing any it had from that date. */
    public void setDated(String sheetId, String key, String value, LocalDate from) {
        jdbc.update("DELETE FROM setting_value WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
                sheetId, key, from);
        jdbc.update("INSERT INTO setting_value (sheet_id, setting_key, from_date, val) VALUES (?, ?, ?, ?)",
                sheetId, key, from, value);
    }

    /** The sheet's clerk limit in force on its today: two decimals, or null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return history(sheetId).clerkLimitOn(today(sheetId));
    }

    /** The sheet's cap in force on its today: two decimals, or null when there is none; a person's due-total is at
     *  most it. */
    public BigDecimal cap(String sheetId) {
        return history(sheetId).capOn(today(sheetId));
    }

    /** The sheet's proof threshold by date (null on a date when there is none then): a claim whose due is above the one
     *  in force on its date cannot be settled or approved while it has no proofs. */
    public DatedAmount proofThreshold(String sheetId) {
        return history(sheetId)::proofThresholdOn;
    }

    /** The sheet's floor by date: a claim's live due is at least the floor in force on its date. */
    public DatedAmount floor(String sheetId) {
        return history(sheetId)::floorOn;
    }

    /** The sheet's late percent by date: an overdue claim gains the one in force on its date, of its figure, every
     *  full 30 days. */
    public DatedAmount latePct(String sheetId) {
        return history(sheetId)::latePctOn;
    }

    /** The terms in days a claim of the grade dated on the date gets: the grade's own in force then, else the
     *  sheet's in force then. */
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return history(sheetId).termsFor(grade, date);
    }

    /** The sheet's permission matrix: the roles each action is open to. */
    public Permissions permissions(String sheetId) {
        Map<String, String> roles = new HashMap<>();
        jdbc.query("SELECT action, roles FROM sheet_permission WHERE sheet_id = ?",
                rs -> {
                    roles.put(rs.getString(1), rs.getString(2));
                }, sheetId);
        return new Permissions(roles);
    }

    /** Set the roles the action is open to (blank: the standing rule). */
    public void setPermission(String sheetId, String action, String roles) {
        jdbc.update("DELETE FROM sheet_permission WHERE sheet_id = ? AND action = ?", sheetId, action);
        if (!roles.isEmpty()) {
            jdbc.update("INSERT INTO sheet_permission (sheet_id, action, roles) VALUES (?, ?, ?)", sheetId, action, roles);
        }
    }

    /** The sheet's policy date: null when blank (the sheet's today is the policy date then). */
    public LocalDate policyDate(String sheetId) {
        return jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPolicyDate(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's period numbering from: null when blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's today: dated settings are shown, and saved by default, as of it. */
    public LocalDate today(String sheetId) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }
}
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useClaims } from '../claims/claims';
import type { Late } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';

/** The sheet's settings: the clerk limit with two decimals ('' when there is none) and the floor with two
 *  decimals (a claim's live due is at least it), and the terms in days (a claim's due-by is its date plus them), and
 *  the late percent with two decimals (an overdue claim gains it, of its figure, every full 30 days), and the
 *  policy date (yyyy-mm-dd; '' when blank: the sheet's today) a claim's live figures round by, and the period numbering from (yyyy-mm-dd; '' when off: on or after it, by
 *  the sheet's today, a claim opened is numbered within its period), and each grade's own terms in days ('' when the
 *  grade has none: it uses the sheet's terms), and the cap with two decimals ('' when there is none: a person's
 *  due-total is at most it), and the proof threshold with two decimals ('' when there is none: a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof). A claim's due-by is fixed when it is created. Each is the value in force on the sheet's
 *  today; `dated` holds every value recorded for the settings that carry a figure, by key (clerk-limit, floor, terms,
 *  terms-A/B/C, late-pct, cap, proof-threshold), oldest from-date first. `perms` is the permission matrix (not dated): for
 *  each action the roles that may take it, comma separated ('' when blank: the standing rule). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string;
  periodNumberingFrom: string; gradeTerms: Record<string, string>; cap: string; proofThreshold?: string; dated?: Record<string, Dated[]>;
  perms?: Record<string, string> };

/** A dated setting's value ('' when blank) in force from its from-date (yyyy-mm-dd). */
export type Dated = { from: string; value: string };

/** A dated figure as it applies to a date (yyyy-mm-dd): the value in force on it. */
export type DatedValue = (date: string) => string;

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else the
 *  sheet's starting value. */
export function valueOn(values: Dated[] | undefined, start: string, date: string): string {
  let found: Dated | undefined;
  for (const v of values ?? []) {
    if (v.from <= date && (!found || found.from < v.from)) found = v;
  }
  return found ? found.value : start;
}

/** The actions the permission matrix covers, in order. */
export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

/** The grades that may have terms of their own. */
export const GRADES = ['A', 'B', 'C'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's settings as they are now. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's floor by date: a claim's live due is at least the one in force on its date (the starting floor
 *  while the settings load). */
export function useFloor(sheetId: string): DatedValue {
  const dated = useSettings(sheetId).data?.dated?.floor;
  return useMemo(() => (date: string) => valueOn(dated, DEFAULT_FLOOR, date), [dated]);
}

/** The sheet's cap in force ('' when there is none, or while the settings load). */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The sheet's terms in force, in days (the starting terms while the settings load). */
export function useTerms(sheetId: string): number {
  return Number(useSettings(sheetId).data?.terms ?? DEFAULT_TERMS);
}

/** What the late charge follows now: the late percent by date (a claim gains the one in force on its date) and the sheet's today; and how claims round:
 *  the policy date in force (blank: the sheet's today) and the dates of the sheet's numbered claims. */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId);
  const claims = useClaims(sheetId).data;
  const numbered = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number as string, c.date])),
    [claims],
  );
  const dated = settings?.dated?.['late-pct'];
  const pct = useMemo(() => (date: string) => valueOn(dated, DEFAULT_LATE_PCT, date), [dated]);
  return { pct, today,
    policy: settings?.policyDate || today, numbered };
}
